use vstd::prelude::*;

verus! {
    fn atleast_2d(arr: Vec<f32>) -> (result: Vec<Vec<f32>>)
        ensures
            result.len() == 1,
            result[0].len() == arr.len(),
            forall |i: nat| 0 <= i < arr.len() ==> result[0][i] == arr[i],
    {
        let mut result: Vec<Vec<f32>> = vec![vec![]]; // Initialize a 2D vector with one empty row
        let mut idx: usize = 0;

        // Fill the first row with elements from the input array
        while idx < arr.len()
            invariant
                result.len() == 1,
                result[0].len() == idx,
                idx <= arr.len(),
                forall |i: nat| 0 <= i < idx ==> result[0][i] == arr[i],
            decreases arr.len() - idx,
        {
            result[0].push(arr[idx]); // Add the current element to the row
            idx += 1; // Move to the next index
        }

        result // Return the constructed 2D array
    }
}

